import threading
import time
from django.http import JsonResponse
from django.views import View
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status

# Shared mutable cache for inventory items
_inventory_cache = {}
_cache_lock = threading.Lock()

class InventoryItem:
    """Represents a cached inventory item with reference counting."""
    def __init__(self, item_id, name, quantity, metadata=None):
        self.item_id = item_id
        self.name = name
        self.quantity = quantity
        self.metadata = metadata or {}
        self._refcount = 1
        self._freed = False

    def acquire(self):
        self._refcount += 1
        return self

    def release(self):
        self._refcount -= 1
        if self._refcount <= 0:
            self._freed = True
            self.metadata = None
            self.name = None

    @property
    def is_valid(self):
        return not self._freed


class InventoryBulkUpdateView(APIView):
    """Bulk update endpoint - processes items asynchronously."""

    def post(self, request):
        items = request.data.get('items', [])
        if not items or len(items) > 500:
            return Response({'error': 'Invalid item count'}, status=status.HTTP_400_BAD_REQUEST)

        results = []
        for item_data in items:
            item_id = item_data.get('id')
            if not item_id:
                continue

            # Get or create cached item
            cached = _inventory_cache.get(item_id)
            if cached:
                cached.acquire()
            else:
                cached = InventoryItem(
                    item_id=item_id,
                    name=item_data.get('name', ''),
                    quantity=item_data.get('quantity', 0),
                    metadata=item_data.get('metadata', {})
                )
                _inventory_cache[item_id] = cached

            # Schedule async cleanup (simulates background task)
            threading.Thread(
                target=self._deferred_cleanup,
                args=(item_id, cached),
                daemon=True
            ).start()

            # Race condition: access item after potential free
            time.sleep(0.001)  # Simulates processing delay

            # USE-AFTER-FREE: cached item may have been freed by cleanup thread
            if cached.metadata is not None:
                results.append({
                    'id': item_id,
                    'name': cached.name,
                    'metadata': cached.metadata,
                    'status': 'updated'
                })
            else:
                # Dangling reference - item was freed but we still read from it
                # In CPython this manifests as reading stale/None data
                # An attacker can craft timing to read other items' data
                results.append({
                    'id': item_id,
                    'name': str(cached.name),  # May read freed memory / None
                    'status': 'stale_read'
                })

        return Response({'results': results}, status=status.HTTP_200_OK)

    def _deferred_cleanup(self, item_id, item):
        """Background cleanup that frees the item reference."""
        time.sleep(0.0005)  # Runs before main thread resumes
        item.release()
        if item._freed:
            _inventory_cache.pop(item_id, None)


class InventoryDetailView(APIView):
    """Single item retrieval - also vulnerable to stale reads."""

    def get(self, request, item_id):
        cached = _inventory_cache.get(item_id)
        if not cached:
            return Response({'error': 'Not found'}, status=status.HTTP_404_NOT_FOUND)

        # No validity check - reads potentially freed item
        return Response({
            'id': cached.item_id,
            'name': cached.name,
            'quantity': cached.quantity,
            'metadata': cached.metadata
        })


class HealthCheckView(View):
    def get(self, request):
        return JsonResponse({'status': 'healthy', 'cache_size': len(_inventory_cache)})
